    let passwordValidated: boolean = l()
      .if({
        logic: () =>
          l({
            logic: () => inputCard.Password === this.InputCard.Password,
            description: "inputCard.Password=InputCard.Password",
          }),
        description: "inputCard.Password=InputCard.Password",
        then: l({
          logic: () => true,
          description: "true",
        }),
        else: l({
          logic: () => false,
          description: "false",
        }),
      })
      .build().pass;
